mapper.select:
select earned_count as earnedCount, held_count as heldCount, used_count as usedCount
from group_buy_skip_account
where user_id = #{userId} and source = #{source} and channel = #{channel}

mapper.update:
update group_buy_skip_account set held_count = held_count + 1
where user_id = #{userId} and source = #{source} and channel = #{channel}
  and earned_count div 2 > held_count + used_count

update group_buy_skip_account
set earned_count = earned_count + #{earnedCount}, held_count = held_count + #{heldCount},
    used_count = used_count + #{usedCount}
where user_id = #{userId} and source = #{source} and channel = #{channel}
  and earned_count + #{earnedCount} >= 0 and held_count + #{heldCount} >= 0
